-- ISSUE-HYGIENE-2 (2026-10-26, pillar autonomy; follows migrations/2026-10-26-issue-hygiene-1.sql and qnfo-observability 1.5.3)
--
-- qnfo-observability 1.5.3 writes the issue_ledger fingerprint into the escalation copy it files ("... , fp=<fingerprint>;" at the end of the description), so a
-- copy is found by the ledger row it came from however that row's title moves. The hourly workflow issue-meta-fold matched a copy by whole title, or by tool for
-- the "[self-heal] tool X failing ..." family, which covers the copies filed before 1.5.3 and nothing else: a copy of another ledger family whose title moved
-- would never close. This file replaces the workflow definition with the same eleven statements except rule ledger-escalation-resolved, which now also matches
-- by the fingerprint tag. Nothing else changes: the ledger, the other five rules, the one-time rules of hygiene-1, the cron.
--
-- Revert: the Rollback line puts the saved hygiene-1 definition back (bak_20261026_fleet_task_issue_meta_fold keeps the first copy, taken before the update).
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE fleet_tasks SET definition = (SELECT b.definition FROM bak_20261026_fleet_task_issue_meta_fold b WHERE b.id = 'issue-meta-fold'), version = version + 1, updated_at = datetime('now') WHERE id = 'issue-meta-fold'
--
-- Verify after apply:
--   SELECT version, instr(definition, 'fp=') > 0 FROM fleet_tasks WHERE id = 'issue-meta-fold';                    -- version 2 or more, 1

CREATE TABLE IF NOT EXISTS bak_20261026_fleet_task_issue_meta_fold AS SELECT id, version, definition, updated_at FROM fleet_tasks WHERE id = 'issue-meta-fold';

UPDATE fleet_tasks SET definition = '{"steps":[{"type":"sql","db":"AUDIT","sql":"INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, ''probe-needed-target-not-open'', x.id, ''moot: issue '' || x.id || '' is '' || x.status || '' ('' || substr(x.title, 1, 80) || ''): the probe this issue asked for belongs to a target that no longer needs one, so the to-do outlived its subject. ISSUE-HYGIENE-1 '' || strftime(''%Y-%m-%d'', ''now''), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM agent_issues m JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = ''issue-'' || m.id JOIN agent_issues x ON x.id = CAST(substr(m.title, 23) AS INTEGER) WHERE m.status = ''open'' AND m.title GLOB ''PROBE-NEEDED-1: issue-[0-9]*'' AND x.status <> ''open'' AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0) ORDER BY m.id LIMIT 200"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, ''code-merge-refused-task-merged'', NULL, ''moot: code task '' || k.id || '' is merged (code_tasks.status, last updated '' || COALESCE(k.updated_at, ''?'') || ''), so the merge refusal this issue recorded no longer holds. ISSUE-HYGIENE-1 '' || strftime(''%Y-%m-%d'', ''now''), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM agent_issues m JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = ''issue-'' || m.id JOIN code_tasks k ON k.id = substr(m.title, 33, instr(substr(m.title, 33) || '' '', '' '') - 1) WHERE m.status = ''open'' AND m.title LIKE ''CODE-MERGE-REFUSED-1: code task ct_%'' AND k.status = ''merged'' AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0) ORDER BY m.id LIMIT 200"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, ''code-loop-exhausted-dod-met'', r.id, ''moot: the definition of done of this issue (the task or a task that replaces it reaches ready_to_publish or later) is met: '' || CASE WHEN r.status IN (''closed'', ''resolved'') THEN ''issue '' || r.id || '' ('' || substr(r.title, 1, 70) || '') is '' || r.status ELSE ''a replacement task for issue '' || r.id || '' is merged or published'' END || ''. ISSUE-HYGIENE-1 '' || strftime(''%Y-%m-%d'', ''now''), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM agent_issues m JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = ''issue-'' || m.id JOIN code_tasks k ON k.id = substr(m.title, 24, instr(substr(m.title, 24) || '' '', '' '') - 1) JOIN agent_issues r ON r.id = CASE WHEN k.id LIKE ''ct_im%'' THEN CAST(substr(k.id, 6) AS INTEGER) WHEN k.goal LIKE ''[issue #%'' THEN CAST(substr(k.goal, 9) AS INTEGER) END WHERE m.status = ''open'' AND m.title LIKE ''CODE-LOOP-EXHAUSTED-1: ct_%'' AND (r.status IN (''closed'', ''resolved'') OR EXISTS (SELECT 1 FROM code_tasks k2 WHERE k2.id <> k.id AND k2.status IN (''merged'', ''published'') AND (k2.id = ''ct_im'' || r.id OR instr(k2.goal, ''[issue #'' || r.id || '']'') > 0))) AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0) ORDER BY m.id LIMIT 200"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, ''ledger-escalation-resolved'', NULL, ''moot: the filing loop resolved its own ledger row (fingerprint '' || (SELECT l.fingerprint FROM issue_ledger l WHERE (instr(COALESCE(m.description, ''''), ''fp='' || l.fingerprint || '';'') > 0 OR (l.title = m.title OR (m.title LIKE ''[self-heal] tool %'' AND l.title LIKE ''[self-heal] tool %'' AND substr(l.title, 18, instr(substr(l.title, 18) || '' '', '' '') - 1) = substr(m.title, 18, instr(substr(m.title, 18) || '' '', '' '') - 1)))) AND l.status IN (''resolved'', ''muted'') ORDER BY l.last_seen DESC LIMIT 1) || '', last seen '' || (SELECT l.last_seen FROM issue_ledger l WHERE (instr(COALESCE(m.description, ''''), ''fp='' || l.fingerprint || '';'') > 0 OR (l.title = m.title OR (m.title LIKE ''[self-heal] tool %'' AND l.title LIKE ''[self-heal] tool %'' AND substr(l.title, 18, instr(substr(l.title, 18) || '' '', '' '') - 1) = substr(m.title, 18, instr(substr(m.title, 18) || '' '', '' '') - 1)))) AND l.status IN (''resolved'', ''muted'') ORDER BY l.last_seen DESC LIMIT 1) || '') and no open ledger row remains for it, so this escalation copy has nothing left to track. ISSUE-HYGIENE-1 '' || strftime(''%Y-%m-%d'', ''now''), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM agent_issues m JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = ''issue-'' || m.id WHERE m.status = ''open'' AND instr(COALESCE(m.description, ''''), ''AUTO-ESCALATION from evReview'') = 1 AND EXISTS (SELECT 1 FROM issue_ledger l WHERE (instr(COALESCE(m.description, ''''), ''fp='' || l.fingerprint || '';'') > 0 OR (l.title = m.title OR (m.title LIKE ''[self-heal] tool %'' AND l.title LIKE ''[self-heal] tool %'' AND substr(l.title, 18, instr(substr(l.title, 18) || '' '', '' '') - 1) = substr(m.title, 18, instr(substr(m.title, 18) || '' '', '' '') - 1)))) AND l.status IN (''resolved'', ''muted'')) AND NOT EXISTS (SELECT 1 FROM issue_ledger l WHERE (instr(COALESCE(m.description, ''''), ''fp='' || l.fingerprint || '';'') > 0 OR (l.title = m.title OR (m.title LIKE ''[self-heal] tool %'' AND l.title LIKE ''[self-heal] tool %'' AND substr(l.title, 18, instr(substr(l.title, 18) || '' '', '' '') - 1) = substr(m.title, 18, instr(substr(m.title, 18) || '' '', '' '') - 1)))) AND l.status IN (''open'', ''acknowledged'')) AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0) ORDER BY m.id LIMIT 200"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, ''owner-task-names-closed-issue'', r.id, ''moot: the task asks for the fix of issue '' || r.id || '' ('' || substr(r.title, 1, 70) || ''), which is '' || r.status || '' with close evidence: '' || substr(COALESCE((SELECT x.close_evidence FROM issue_triage x WHERE x.issue_id = r.id), ''(none recorded)''), 1, 160) || '' ISSUE-HYGIENE-1 '' || strftime(''%Y-%m-%d'', ''now''), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM agent_issues m JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = ''issue-'' || m.id JOIN agent_issues r ON r.id = CAST(substr(m.title, instr(m.title, ''(issue #'') + 8) AS INTEGER) WHERE m.status = ''open'' AND m.source = ''qnfo-fleet-dashboard:owner-request'' AND m.title LIKE ''OWNER-TASK-op-%'' AND instr(m.title, ''(issue #'') > 0 AND r.id <> m.id AND r.status IN (''closed'', ''resolved'') AND instr(m.title, substr(r.title, 1, MIN(30, instr(r.title || '':'', '':'') - 1))) > 0 AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0) ORDER BY m.id LIMIT 200"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, ''owner-prompt-twin'', s.id, ''superseded by '' || s.id || '' ('' || substr(s.title, 1, 100) || '', open): the same owner prompt filed again, because the dashboard intake dedupes by whole title and every title carries its own op id. The older ticket carries the work. ISSUE-HYGIENE-1 '' || strftime(''%Y-%m-%d'', ''now''), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM agent_issues m JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = ''issue-'' || m.id JOIN agent_issues s ON s.id = (SELECT MIN(o.id) FROM agent_issues o WHERE o.status = ''open'' AND o.id < m.id AND o.source = m.source AND (o.title LIKE ''OWNER-TASK-op-%'' OR o.title LIKE ''OWNER-NOTE-%'') AND lower(trim(substr(o.title, instr(o.title, '': '') + 2))) = lower(trim(substr(m.title, instr(m.title, '': '') + 2)))) WHERE m.status = ''open'' AND m.source = ''qnfo-fleet-dashboard:owner-request'' AND (m.title LIKE ''OWNER-TASK-op-%'' OR m.title LIKE ''OWNER-NOTE-%'') AND instr(m.title, '': '') > 0 AND length(lower(trim(substr(m.title, instr(m.title, '': '') + 2)))) >= 20 AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0) ORDER BY m.id LIMIT 200"},{"type":"sql","db":"AUDIT","sql":"UPDATE remediation_contracts SET status = ''superseded'', last_verdict = ''superseded:closure-superseded (ISSUE-HYGIENE-1)'', last_attempt_at = datetime(''now'') WHERE class IN (SELECT f.contract_class FROM issue_fold_ledger f WHERE f.applied = 0 AND f.contract_class IS NOT NULL) AND status IN (''monitoring'', ''escalated'', ''active'', ''holding'', ''needs-machine-probe'', ''probe-review-refused'')"},{"type":"sql","db":"AUDIT","sql":"UPDATE agent_issues SET close_channel = ''workflow:ISSUE-HYGIENE-1 '' || (SELECT f.rule FROM issue_fold_ledger f WHERE f.issue_id = agent_issues.id AND f.applied = 0 ORDER BY f.id DESC LIMIT 1) WHERE status = ''open'' AND id IN (SELECT issue_id FROM issue_fold_ledger WHERE applied = 0)"},{"type":"sql","db":"AUDIT","sql":"UPDATE issue_triage SET triage_state = ''closed'', triaged_at = datetime(''now''), close_evidence = (SELECT f.evidence FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.applied = 0 ORDER BY f.id DESC LIMIT 1) WHERE issue_id IN (SELECT f.issue_id FROM issue_fold_ledger f JOIN agent_issues a ON a.id = f.issue_id WHERE f.applied = 0 AND a.status = ''open'')"},{"type":"sql","db":"AUDIT","sql":"UPDATE agent_issues SET status = ''closed'', updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE status = ''open'' AND id IN (SELECT f.issue_id FROM issue_fold_ledger f JOIN issue_triage t ON t.issue_id = f.issue_id WHERE f.applied = 0 AND t.triage_state = ''closed'' AND t.close_evidence = f.evidence)"},{"type":"sql","db":"AUDIT","sql":"UPDATE issue_fold_ledger SET applied = 1, applied_at = datetime(''now'') WHERE applied = 0 AND (SELECT a.status FROM agent_issues a WHERE a.id = issue_fold_ledger.issue_id) <> ''open''"}]}', version = version + 1, updated_at = datetime('now') WHERE id = 'issue-meta-fold';
